<template>
 <view class="page-heading"><view><view class="eyebrow">GROW AT THEIR OWN PACE</view><text class="page-title">陪孩子，慢慢学会</text><text class="page-subtitle">数据只保存在这台设备上。没有广告，也没有公开排名。</text></view></view>
 <view class="parent-grid"><WPCard><text class="section-title">最近 7 天</text><view class="weekly-chart" role="img" :aria-label="weekly.map(d=>`${d.label}学习${d.count}次`).join('，')"><view v-for="day in weekly" :key="day.date" class="chart-column"><text class="small strong">{{day.count}}</text><view class="chart-track"><view class="chart-bar" :style="{height:(day.count?Math.max(8,day.count/max*100):0)+'%'}"/></view><text class="small muted">{{day.label}}</text></view></view><view class="mini-stats"><view><text class="metric">{{profile.db.history.length}}</text><text class="small muted">累计有效学习</text></view><view><text class="metric">{{accuracy}}%</text><text class="small muted">累计正确率</text></view><view><text class="metric">{{review.weak.length}}</text><text class="small muted">需要再熟悉</text></view></view><text class="small muted block">正确率是练习反馈，不是对孩子的评价。建议先听音、再回想、最后拼写。</text></WPCard>
 <WPCard><text class="section-title">家长设置</text><text class="muted block">新词每天最多 {{profile.db.dailyLimit}} 个。到期复习优先，低于 80% 时先巩固当前课。</text><view v-if="!unlocked" class="parent-gate"><text>请家长回答：7 × 8 = ?</text><input class="spelling-input" type="number" v-model="gateAnswer" aria-label="家长验证答案" placeholder="输入答案"/><WPButton kind="secondary" @click="unlock">打开家长设置</WPButton></view><template v-else><ParentLearningSettings/><text v-if="activities.recommendation" class="notice">{{activities.recommendation}}</text><view class="notice">默认完全离线；不使用账号、定位、相机或云同步。跟读仅在主动录音时使用麦克风，录音不上传。</view><text class="section-title">删除学习数据</text><text class="muted block">会清除本设备的单词、进度、灵石与宠物成长。此操作无法撤销。</text><checkbox-group @change="keepCourses=($event as any).detail.value.includes('keep')"><label class="course-check"><checkbox value="keep" :checked="keepCourses"/><text>保留已安装课程内容</text></label></checkbox-group><input class="spelling-input" v-model="deleteText" aria-label="输入删除确认文字" placeholder="输入：删除学习数据"/><WPButton kind="danger" :disabled="deleteText!=='删除学习数据'" @click="erase">删除本设备学习数据</WPButton></template><text v-if="message" class="notice" role="status">{{message}}</text></WPCard>
 </view>
 <view v-if="unlocked" class="parent-course-stack"><WPCard><CourseManagement/></WPCard><WPCard><LearningBackupPanel/></WPCard></view>
</template>
<script setup lang="ts">
import CourseManagement from '../../components/course/CourseManagement.vue'
import LearningBackupPanel from '../../components/course/LearningBackupPanel.vue'
import {useActivitiesStore} from '../../stores/activities'
import {clearInstalledCourses} from '../../services/content/StorageRepository'
import {stopAudio} from '../../services/audio'
import ParentLearningSettings from '../../components/parent/ParentLearningSettings.vue'

import WPButton from '../../components/wp-button/WPButton.vue'
import WPCard from '../../components/wp-card/WPCard.vue'
import {useStudyPresentation} from '../../stores/study-presentation';import {useWordbookStore} from '../../stores/wordbook';import {computed,ref} from 'vue';import {useProfileStore} from '../../stores/profile';import {useReviewStore} from '../../stores/review';import {localDate} from '../../../packages/core_learning';const profile=useProfileStore(),review=useReviewStore(),unlocked=ref(false),gateAnswer=ref(''),deleteText=ref(''),message=ref(''),keepCourses=ref(true),activities=useActivitiesStore();const weekly=computed(()=>Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-6+i);const date=localDate(day);return {date,label:`${day.getMonth()+1}/${day.getDate()}`,count:profile.db.history.filter(a=>localDate(new Date(a.at))===date).length}}));const max=computed(()=>Math.max(1,...weekly.value.map(d=>d.count)));const accuracy=computed(()=>profile.db.history.length?Math.round(profile.db.history.filter(a=>a.correct).length/profile.db.history.length*100):0);function unlock(){if(gateAnswer.value==='56'){unlocked.value=true;message.value=''}else message.value='请家长完成验证。'}async function erase(){if(unlocked.value&&deleteText.value==='删除学习数据'){try{stopAudio();profile.erase();const activitiesCleared=activities.reset();if(!keepCourses.value)await clearInstalledCourses();const presentationCleared=useStudyPresentation().reset();const marksCleared=useWordbookStore().reset();review.refresh();deleteText.value='';message.value=presentationCleared&&marksCleared&&activitiesCleared?'学习数据已删除，可以重新开始。':'学习数据已删除，界面标记未清除，请检查设备存储并重试。'}catch{message.value='删除失败，请检查设备存储。'}}}</script>

